







/* ================================================================
   RENDER
   ================================================================ */
/* ============ VUE ISOMÉTRIQUE (tout le jeu) ============ */
const ISO=true; const ISO_TW=64, ISO_TH=32, ISO_WH=42; let isoOX=0, isoOY=0;   /* vue unique */
/* Projection monde -> écran. Globale : les fonctions de dessin appelées hors de
   renderIso (projectiles, fantômes) en ont besoin. */
const isoPx=(wx,wy)=>{const fx=wx/TS,fy=wy/TS;return{x:(fx-fy)*(ISO_TW/2)+isoOX,y:(fx+fy)*(ISO_TH/2)+isoOY};};
function isoShade(hex,amt){let c=(hex||'#444').replace('#','');if(c.length===3)c=c.split('').map(x=>x+x).join('');
  let r=parseInt(c.slice(0,2),16),g=parseInt(c.slice(2,4),16),b=parseInt(c.slice(4,6),16);
  const f=v=>Math.max(0,Math.min(255,v+amt));return 'rgb('+f(r)+','+f(g)+','+f(b)+')';}
function isoDiamond(sx,sy,w,h){ctx.beginPath();ctx.moveTo(sx,sy-h/2);ctx.lineTo(sx+w/2,sy);ctx.lineTo(sx,sy+h/2);ctx.lineTo(sx-w/2,sy);ctx.closePath();}
/* ==== TILESETS ISO (PixelLab) ==== */
const TILESETS={};
(function(){const _D={"pool": {"floor": "data:image/png;base64,", "wall": "data:image/png;base64,"}, "ice": {"floor": "data:image/png;base64,", "wall": "data:image/png;base64,"}, "wood": {"floor": "data:image/png;base64,", "wall": "data:image/png;base64,"}, "church": {"floor": "data:image/png;base64,", "wall": "data:image/png;base64,"}, "gym": {"floor": "data:image/png;base64,", "wall": "data:image/png;base64,"}};for(const k in _D){const t={floor:new Image(),wall:new Image(),gap:1};t.floor.src=_D[k].floor;t.wall.src=_D[k].wall;TILESETS[k]=t;}})();
TILESETS.arena={floor:new Image(),gap:1};TILESETS.arena.floor.src="data:image/png;base64,";
TILESETS.town={floor:new Image(),wall:new Image(),gap:1};TILESETS.town.floor.src="data:image/png;base64,";TILESETS.town.wall.src="data:image/png;base64,";
TILESETS.cave={wall:new Image(),gap:1};TILESETS.cave.floor=new Image();TILESETS.cave.floor.src="data:image/png;base64,";TILESETS.cave.wall.src="data:image/png;base64,";
/* La Fosse ne partage PLUS les murs des grottes.
   Le nouveau mur livré le 6 août fait passer les GROTTES de 11,0 à 33,3
   d'écart avec leur sol : gain net, on le garde pour elles. Mais le sol de
   l'arène est clair (#505B5F, luminance 75) et ce mur est sombre (#4D505F,
   59) : l'écart tomberait à 4,7 — pire que l'ancien, qui était à 27,7.
   L'arène garde donc l'ancienne roche tant que son SOL n'est pas refait. */
TILESETS.arena.wall=new Image();TILESETS.arena.wall.src="data:image/png;base64,";
function _tsRect(img,i){const w=(img.naturalWidth-3)>>2,hh=(img.naturalHeight-3)>>2,c=i&3,r=i>>2;return[c*(w+1),r*(hh+1),w,hh];}
function tileVariant(tx,ty,n){let h=((tx*73856093)^(ty*19349663))>>>0;h=(h^(h>>>13))>>>0;return h%n;}
function _floorish(x,y){if(x<0||y<0||x>=level.w||y>=level.h)return false;const c=level.grid[idx(level.w,x,y)];return c===T_FLOOR||c===T_GATE||c===T_CAVE||c===T_STAIR;}
/* dual-grid sol : coin "carrelage"(A) vs "colle"(B). B = bord de mur (bas de sol) ou motif déco. */
function _matA(x,y){ if(!_floorish(x,y))return false;
  // bande de colle au pied des murs — CONTINUE (8 voisins, coins inclus)
  for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dx||dy){if(!_floorish(x+dx,y+dy))return false;}}
  // chemin inscrusté (voulu, suit le tracé)
  if(level.deco&&level.deco[idx(level.w,x,y)])return false;
  return true; }
function drawIsoFloor(sx,sy,c,TH,tx,ty){
  const ts=TILESETS[level.theme];
  if(ts&&ts.floor&&c!==T_GATE&&c!==T_STAIR&&ts.floor.complete&&ts.floor.naturalWidth){
    const v=tileVariant(tx|0,ty|0,16),fc=v&3,fr=v>>2,g=ts.gap;
    ctx.imageSmoothingEnabled=false;
    ctx.drawImage(ts.floor, fc*(ts.ftw+g),fr*(ts.fth+g),ts.ftw,ts.fth, sx-ISO_TW/2, sy-ISO_TH/2, ISO_TW, ISO_TH);
    return;
  }
  isoDiamond(sx,sy,ISO_TW,ISO_TH);
  ctx.fillStyle=(c===T_GATE)?'#c8a24a':(c===T_STAIR?'#3a4668':(TH.floor[0]));ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.16)';ctx.lineWidth=1;ctx.stroke();
  if(c===T_GATE){ctx.fillStyle='rgba(244,211,94,'+(0.4+0.3*Math.sin(performance.now()/300))+')';isoDiamond(sx,sy,ISO_TW*0.6,ISO_TH*0.6);ctx.fill();}
}
function drawIsoWall(sx,sy,TH,alpha,tx,ty){
  const ts=TILESETS[level.theme];
  if(ts&&ts.wall&&ts.wall.complete&&ts.wall.naturalWidth){
    let idx16=15;
    if(_floorish((tx|0)+1,ty|0)||_floorish((tx|0)-1,ty|0)||_floorish(tx|0,(ty|0)+1)||_floorish(tx|0,(ty|0)-1))idx16=0;
    const wc=idx16&3,wr=idx16>>2,g=ts.gap;
    ctx.save();ctx.globalAlpha=(alpha==null?1:alpha);ctx.imageSmoothingEnabled=false;
    ctx.drawImage(ts.wall, wc*(ts.wtw+g),wr*(ts.wth+g),ts.wtw,ts.wth, sx-ISO_TW/2, sy-ISO_TW*0.75, ISO_TW, ISO_TW);
    ctx.restore();return;
  }
  ctx.save();ctx.globalAlpha=(alpha==null?1:alpha);
  const w=ISO_TW,h=ISO_TH,WH=ISO_WH,topY=sy-WH;
  const R=[sx+w/2,topY],B=[sx,topY+h/2],L=[sx-w/2,topY],T=[sx,topY-h/2];
  const B2=[sx,sy+h/2],R2=[sx+w/2,sy],L2=[sx-w/2,sy];
  ctx.fillStyle=isoShade(TH.wall[0],-14);ctx.beginPath();ctx.moveTo(B[0],B[1]);ctx.lineTo(R[0],R[1]);ctx.lineTo(R2[0],R2[1]);ctx.lineTo(B2[0],B2[1]);ctx.closePath();ctx.fill();
  ctx.fillStyle=isoShade(TH.wall[1],-30);ctx.beginPath();ctx.moveTo(L[0],L[1]);ctx.lineTo(B[0],B[1]);ctx.lineTo(B2[0],B2[1]);ctx.lineTo(L2[0],L2[1]);ctx.closePath();ctx.fill();
  ctx.fillStyle=TH.wall[0];ctx.beginPath();ctx.moveTo(T[0],T[1]);ctx.lineTo(R[0],R[1]);ctx.lineTo(B[0],B[1]);ctx.lineTo(L[0],L[1]);ctx.closePath();ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.25)';ctx.lineWidth=1;ctx.stroke();
  ctx.restore();
}
/* marqueur visible pour la sortie de grotte (escalier) et la porte d'acte */
function drawExitMark(sx,sy,isStair){
  const t=performance.now(), pulse=0.55+0.45*Math.sin(t/380);
  const col=isStair?[127,208,255]:[244,211,94];
  const rgba=(a)=>'rgba('+col[0]+','+col[1]+','+col[2]+','+a+')';
  ctx.save();
  // halo au sol
  ctx.fillStyle=rgba(0.16*pulse+0.10);
  ctx.beginPath();ctx.ellipse(sx,sy,ISO_TW*0.46,ISO_TH*0.46,0,0,6.28);ctx.fill();
  // losange lumineux
  ctx.strokeStyle=rgba(0.55+0.35*pulse);ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(sx,sy-ISO_TH*0.42);ctx.lineTo(sx+ISO_TW*0.42,sy);
  ctx.lineTo(sx,sy+ISO_TH*0.42);ctx.lineTo(sx-ISO_TW*0.42,sy);ctx.closePath();ctx.stroke();
  // faisceau + flèche
  ctx.fillStyle=rgba(0.10+0.10*pulse);
  ctx.beginPath();ctx.moveTo(sx-ISO_TW*0.30,sy);ctx.lineTo(sx+ISO_TW*0.30,sy);
  ctx.lineTo(sx+ISO_TW*0.16,sy-46);ctx.lineTo(sx-ISO_TW*0.16,sy-46);ctx.closePath();ctx.fill();
  ctx.fillStyle=rgba(0.85);ctx.font='bold 15px Trebuchet MS';ctx.textAlign='center';
  ctx.fillText(isStair?'▲':'▼',sx,sy-30-3*pulse);
  /* LE NIVEAU REQUIS S'AFFICHE SUR LA PORTE.

     Il n'était annoncé que par un message de 3 secondes, au moment où l'on
     essayait de passer. Un joueur qui a tué le gardien, brisé la relique et
     qui voit la porte s'ouvrir n'a aucune raison de soupçonner un plancher
     de niveau : il rate l'annonce une fois, et il ne sait plus quoi faire.

     Sur la porte, l'information est là tant qu'elle est vraie. */
  const _bloc=porteBloquee();
  etiquette(sx,sy-52,isStair?'Sortie':(level&&level.kind==='village'?nomActeCourant():'Porte'),
            _bloc?'#ff9a5a':(isStair?'#cfe8ff':'#ffe89a'),11);
  if(_bloc)etiquette(sx,sy-38,'⚠ Niveau '+_bloc.min+' conseillé — tu es niveau '+player.lvl,'#ff9a5a',10);
  ctx.textAlign='left';ctx.restore();
}

/* La porte devant laquelle on se tient est-elle au-dessus du niveau du
   héros ? Depuis la 8.74 elle ne refuse plus rien : elle avertit.
   Renvoie {n, min, nom} si oui, null sinon. Sert à l'étiquette de la porte
   ET au message : une seule source, deux affichages qui ne peuvent pas se
   contredire. */
function porteBloquee(){
  if(!level)return null;
  const n=(level.kind==='village')?acteCourant():((level.actNum||0)+1);
  if(n>=ACTS.length)return null;
  const min=ACT_MIN[n]||1;
  if(player.lvl>=min||n<=maxAct)return null;
  return {n:n,min:min,nom:(ACTS[n]&&ACTS[n].court)||'cet acte'};
}
/* L'acte vers lequel ouvre la porte du village : le plus avancé atteint. */
function acteCourant(){
  let a=Math.max(0,Math.min(ACTS.length-1,maxAct||0));
  /* On ne propose pas une porte qui refusera le passage. */
  while(a>0 && player.lvl<(ACT_MIN[a]||1))a--;
  return a;
}
function nomActeCourant(){ const A=ACTS[acteCourant()]; return (A&&A.court)||'la Piscine'; }
/* ================================================================
   CACHE DU SOL  —  le chantier le plus rentable du moteur

   Mesuré avant : à l'acte 1, écran de téléphone, carte explorée, une seule
   image de jeu demandait 1 391 appels `drawImage` pour le SOL et 380 pour les
   murs, plus 1 248 losanges remplis pour le voile. Soit 99,7 % du dessin
   consacré à un décor qui ne bouge pas. À 60 images par seconde : 83 000
   appels par seconde.

   Le sol se dessine en un seul passage, AVANT le tri par profondeur : il
   n'interagit avec rien. Il est donc entièrement cachable.

   On découpe la carte en DALLES de 8x8 sommets, chacune rendue une fois dans
   son propre canevas hors écran. Une dalle n'est refaite que si son contenu
   change — c'est-à-dire quand `seen` évolue en la traversant. À l'écran, on ne
   recopie que les dalles visibles : une poignée de `drawImage` au lieu de 1 391.

   Les MURS restent dans le flux trié : ils doivent pouvoir passer devant ou
   derrière le héros, et s'estomper. 380 appels, c'est tenable.
   ================================================================ */
const DALLE=8;                       // côté d'une dalle, en sommets de grille
function _cacheSol(){
  if(renderIso._dLvl!==level.id){ renderIso._dLvl=level.id; renderIso._dal={}; }
  return renderIso._dal;
}
/* Une dalle a changé : on la jette. Appelé quand une case devient vue. */
function salirDalle(tx,ty){
  const c=renderIso._dal; if(!c)return;
  /* Une case touche jusqu'à quatre sommets, donc jusqu'à quatre dalles.
     On NE SUPPRIME PAS l'entrée : on garde le canevas pour le réutiliser, et
     on marque seulement qu'il faut le repeindre. */
  for(const [ax,ay] of [[0,0],[1,0],[0,1],[1,1]]){
    const k=(((tx+ax)/DALLE)|0)+':'+(((ty+ay)/DALLE)|0);
    const D=c[k]; if(D)D.pret=false;
  }
}
let _dalleRendues=0;   /* compteur de diagnostic */
/* Le tracé d'une dalle, dans un contexte quelconque et à un décalage donné.
   Sert deux fois : pour remplir le canevas de la dalle, et pour dessiner
   directement à l'écran quand le budget de reconstruction est épuisé. */
function _dalleDessin(dx,dy,c2,ox,oy){
  const ts=TILESETS[level.theme];
  const X0=dx*DALLE, Y0=dy*DALLE, X1=X0+DALLE, Y1=Y0+DALLE;
  const w=level.w,h=level.h,isVil=level.kind==='village';
  let vide=true;
  c2.imageSmoothingEnabled=false;
  for(let Y=Y0;Y<=Y1;Y++)for(let X=X0;X<=X1;X++){
    if(!(_floorish(X-1,Y-1)||_floorish(X,Y-1)||_floorish(X-1,Y)||_floorish(X,Y)))continue;
    if(!isVil){
      const sa=level.seen[idx(w,clamp(X,0,w-1),clamp(Y,0,h-1))],
            sb=level.seen[idx(w,clamp(X-1,0,w-1),clamp(Y-1,0,h-1))];
      if(!sa&&!sb)continue;
    }
    const fi=(_matA(X-1,Y-1)?8:0)|(_matA(X,Y-1)?4:0)|(_matA(X-1,Y)?2:0)|(_matA(X,Y)?1:0);
    let tsF=ts.floor;
    if(level.bossArena&&TILESETS.arena&&TILESETS.arena.floor.complete&&TILESETS.arena.floor.naturalWidth){
      const ddx=X-level.bossArena.x,ddy=Y-level.bossArena.y;
      if(ddx*ddx+ddy*ddy<level.bossArena.r*level.bossArena.r)tsF=TILESETS.arena.floor;
    }
    const RF=_tsRect(tsF,fi);
    const px=(X-Y)*(ISO_TW/2)+ox, py=(X+Y)*(ISO_TH/2)+oy;
    c2.drawImage(tsF,RF[0],RF[1],RF[2],RF[3], px-ISO_TW/2, py-ISO_TH/2, ISO_TW, ISO_TH);
    /* TEINTE DE RÉGION. Elle n'est appliquée qu'à la construction de la dalle —
       une fois — et `source-atop` la limite au sol déjà peint : elle ne bave
       pas sur le fond transparent. */
    {const _rp=regionDe(level,X,Y);
     /* La salle prime sur la région : c'est elle, le point de repère. */
     let _t=_rp&&_rp.teinte;
     if(level.salle){const _si=level.salle[idx(level.w,clamp(X,0,level.w-1),clamp(Y,0,level.h-1))];
       if(_si>=0&&level.salles&&level.salles[_si])_t=level.salles[_si].teinte||_t;}
     if(_t){
       c2.save();c2.globalCompositeOperation='source-atop';c2.fillStyle=_t;
       c2.beginPath();
       c2.moveTo(px,py-ISO_TH/2);c2.lineTo(px+ISO_TW/2,py);
       c2.lineTo(px,py+ISO_TH/2);c2.lineTo(px-ISO_TW/2,py);
       c2.closePath();c2.fill();c2.restore();
     }}
    if(typeof __DALLE_LOG!=='undefined'&&__DALLE_LOG)
      __DALLE_LOG.push({X:X,Y:Y,fi:fi,src:tsF.src,mx:px-ox,my:py-oy});
    vide=false;
  }
  return vide;
}
/* Boîte écran d'une dalle, en coordonnées monde. */
function _dalleBoite(dx,dy){
  const X0=dx*DALLE, Y0=dy*DALLE, X1=X0+DALLE, Y1=Y0+DALLE;
  const co=[[X0,Y0],[X1,Y0],[X0,Y1],[X1,Y1]].map(([X,Y])=>({
    x:(X-Y)*(ISO_TW/2), y:(X+Y)*(ISO_TH/2)}));
  const minx=Math.min.apply(null,co.map(p=>p.x))-ISO_TW/2-2;
  const maxx=Math.max.apply(null,co.map(p=>p.x))+ISO_TW/2+2;
  const miny=Math.min.apply(null,co.map(p=>p.y))-ISO_TH/2-2;
  const maxy=Math.max.apply(null,co.map(p=>p.y))+ISO_TH/2+2;
  return {ox:minx,oy:miny,w:Math.ceil(maxx-minx),h:Math.ceil(maxy-miny)};
}
/* Construit (ou reconstruit) une dalle. LE CANEVAS EST RÉUTILISÉ : en allouer
   un neuf à chaque fois, c'était 720 Ko de bitmap jeté au ramasse-miettes par
   dalle — et jusqu'à 80 dalles dans la même image à l'entrée d'un niveau. */
function _rendreDalle(dx,dy,vieux){
  _dalleRendues++;
  const B=_dalleBoite(dx,dy);
  let cv=vieux&&vieux.cv;
  if(cv&&(cv.width!==B.w||cv.height!==B.h))cv=null;
  if(!cv){ cv=document.createElement('canvas'); cv.width=B.w; cv.height=B.h; }
  const c2=cv.getContext('2d');
  c2.clearRect(0,0,B.w,B.h);
  const vide=_dalleDessin(dx,dy,c2,-B.ox,-B.oy);
  return {cv:cv, ox:B.ox, oy:B.oy, w:B.w, h:B.h, pret:true, vide:vide};
}
/* BUDGET DE RECONSTRUCTION.

   À l'entrée d'un niveau, 80 dalles étaient construites dans la MÊME image.
   Chacune alloue un canevas d'environ 576 x 320 : 57 Mo d'un coup, plus 80
   remplissages de tuiles. Sur Android, c'est une saccade franche.

   On en reconstruit au plus DEUX par image. Les autres sont dessinées
   directement à l'écran ce tour-ci — un peu plus cher pour cette image, mais
   rien n'est alloué et rien ne clignote — et elles passeront au cache dans
   les images suivantes. En deux secondes tout est en cache. */
const BUDGET_DALLE=2;
function dessinerSolEnCache(cx0,cy0,cx1,cy1){
  if(typeof document==='undefined'||!document.createElement)return false;
  const cache=_cacheSol();
  const d0x=Math.floor(cx0/DALLE), d1x=Math.floor((cx1+1)/DALLE);
  const d0y=Math.floor(cy0/DALLE), d1y=Math.floor((cy1+1)/DALLE);
  ctx.imageSmoothingEnabled=false;
  let budget=BUDGET_DALLE;
  for(let dy=d0y;dy<=d1y;dy++)for(let dx=d0x;dx<=d1x;dx++){
    const k=dx+':'+dy;
    let D=cache[k];
    if(D&&D.pret){
      if(D.cv&&!D.vide)ctx.drawImage(D.cv, Math.round(D.ox+isoOX), Math.round(D.oy+isoOY));
      continue;
    }
    if(budget>0){
      budget--;
      D=_rendreDalle(dx,dy,D); cache[k]=D;
      if(D.cv&&!D.vide)ctx.drawImage(D.cv, Math.round(D.ox+isoOX), Math.round(D.oy+isoOY));
    } else {
      /* pas de budget : on la dessine à l'ancienne, cette image seulement */
      _dalleDessin(dx,dy,ctx,isoOX,isoOY);
    }
  }
  return true;
}
/* ================================================================
   LE VOILE  —  un dégradé, plus 1 248 losanges

   Le brouillard assombrissait chaque case hors du rayon de lumière : un
   losange rempli par case, six opérations de chemin chacun. Il suit le héros,
   il ne peut donc pas être mis en cache — mais il peut être dessiné D'UN SEUL
   COUP, en un dégradé radial centré sur lui. Un remplissage au lieu de 1 248,
   et une bordure douce au lieu d'un escalier de losanges.
   ================================================================ */
function dessinerVoile(){
  const p=isoPx(player.x,player.y);
  /* Le rayon de lumière appartient à la RÉGION : une galerie sombre resserre
     la vue, une étendue gelée l'ouvre. On l'amortit pour éviter un à-coup en
     passant d'une région à l'autre. */
  const _rp=regionEn(level,player.x,player.y);
  const cible=(_rp&&_rp.vision)||7;
  if(dessinerVoile._r==null)dessinerVoile._r=cible;
  dessinerVoile._r+=(cible-dessinerVoile._r)*0.05;
  const R=dessinerVoile._r*TS;
  const r0=R*(ISO_TW/2)/TS, r1=r0*1.55;          // converti à l'échelle iso
  let g;
  try{
    g=ctx.createRadialGradient(p.x,p.y,r0*0.72,p.x,p.y,r1);
    g.addColorStop(0,'rgba(4,6,11,0)');
    g.addColorStop(1,'rgba(4,6,11,0.5)');
  }catch(e){ return; }
  ctx.save();ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.restore();
}

/* Aide de TEST, rendue à son propriétaire.                        (Phase 5)
   Elle vivait dans 19-halos.js, loin de la variable qu'elle écrit — ce
   que la portée globale unique autorisait sans le dire. */
function setDalleCount(v){_dalleRendues=v;}



